import{d as c,C as t,o as g,c as m,j as a,a as n,E as o,a3 as p}from"./chunks/framework.Q4yG9rk_.js";const _=JSON.parse('{"title":"道德经第三十三章","description":"从知人到自知、胜人到自胜，理解知足、力行与身没道存的长久。","frontmatter":{"title":"道德经第三十三章","description":"从知人到自知、胜人到自胜，理解知足、力行与身没道存的长久。","category":"guide","aliases":["道德经第三十三章","老子第三十三章","dao de jing chapter 33"],"source":["王弼《道德真经注》卷二"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-33.md","filePath":"daoism/dao-de-jing/chapter-33.md","lastUpdated":1794189804000}'),u={name:"daoism/dao-de-jing/chapter-33.md"},q=c({...u,setup(b){const s=[{id:"knowing-others-and-oneself",label:"知人者智，自知者明",showLabel:!0,sentences:[[{text:"知",glossary:"zhi"},"人者智，自知者",{text:"明",glossary:"ming"},"。"]],note:["【白话】能了解别人的人有才智，能明察自身的人才称得上明。这里把判断的视线从他人转回自己，强调自察比只会察人更进一步。","【王弼注择要】「知人者智而已矣，未若自知者超智之上也。」注又说「用其智于人，未若用其智于己也」，明确比较智力使用的方向。","【读法】知读 zhī，作认识、了解。这里的智先指知人的才智，不宜直接套入第十九章针对机巧逐名的批评。"]},{id:"overcoming-oneself",label:"胜人者有力，自胜者强",showLabel:!0,sentences:[["胜人者有力，自",{text:"胜",glossary:"sheng"},"者",{text:"强",glossary:"qiang"},"。"]],note:["【白话】能够战胜别人的人有力量，能够克服自身偏执与牵累的人才是强者。后一句把力量的检验转到自身，不以压倒别人作为唯一尺度。","【王弼注择要】「胜人者有力而已矣，未若自胜者无物以损其力。」王弼将自胜与不受外物损其力相连，不单指在外部竞争中取胜。","【读法】自胜的具体内容须连自知、自察来理解，不能把它变成压抑一切情绪或否认身体限度的要求。此处强读 qiáng。"]},{id:"contentment-and-persistent-practice",label:"知足者富",showLabel:!0,sentences:[[{text:"知足",glossary:"zhizu"},"者富。"],[{text:"强行",glossary:"qiangxing"},"者有志。"]],note:["【白话】知道满足的人是富足的；能够勉力践行、坚持行道的人是有志向的。两句并读，既不让欲望无穷追赶，也不因知足而放弃实践。","【王弼注择要】「知足自不失，故富也。」强行下注说「勤能行之，其志必获」，以勤行说明有志，而非只在口头立愿。","【读法】强行读 qiǎng xíng，取勉力实行义，不是现代常说的强行命令他人。知足说的是欲求的分际，不把现实贫困归咎于当事人不懂满足。"]},{id:"remaining-in-ones-proper-ground",label:"不失其所者久",showLabel:!0,sentences:[["不失其",{text:"所",glossary:"suo"},"者久。"]],note:["【白话】不失掉自身所安处、所依循的恰当位置与根本，才可以长久。依王弼，应先明察自己，再衡量力量而行，使行动不离实际所能。","【王弼注择要】「以明自察，量力而行，不失其所，必获久长矣。」本页据此将所连到自察与行事分际，不解释成永远停留在一个外在位置。","【读法】所可连安处、根本来体会；本页采用王弼自察、量力的读法，不将本句写成宿命地守住既定身份或岗位。"]},{id:"the-way-enduring-beyond-death",label:"死而不亡者寿",showLabel:!0,sentences:[["死而不",{text:"亡",glossary:"wang"},"者",{text:"寿",glossary:"shou"},"。"]],note:["【白话】身体虽死，而其所以为生的道不随之消亡，这才称得上寿。这里依王弼，将寿的理解从肉身年数推向所守之道的长存。","【王弼注择要】「虽死而以为生之道不亡，乃得全其寿。」又说「身没而道犹存」，说明身体之死与道之不亡在句中分属不同层次。","【读法】本页采用身没道存的注解，不推出肉身不死或灵魂不灭；后世也常由精神、影响的延续理解本句，但不直接用被人记住代替王注之道。"]}],r=[{id:"zhi",term:"知",sense:2,pinyin:"zhī"},{id:"ming",term:"明",sense:1},{id:"sheng",term:"胜",sense:1},{id:"qiang",term:"强",sense:2,pinyin:"qiáng",context:"自胜者强，将强健的重心放在自身，不指逞强压人。"},{id:"zhizu",term:"知足",sense:1},{id:"qiangxing",term:"强行",sense:1},{id:"suo",term:"所",sense:1},{id:"wang",term:"亡",sense:1},{id:"shou",term:"寿",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return g(),m("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第三十三章",tabindex:"-1"},[n("道德经第三十三章 "),a("a",{class:"header-anchor",href:"#道德经第三十三章","aria-label":'Permalink to "道德经第三十三章"'},"​")],-1)),o(i,{title:"把智与力转向自身，会看见什么",summary:"本章以知人、自知和胜人、自胜两组对照起笔，再说知足、力行、不失其所，最后以死而不亡收束。王弼将智力回用于己，并以身没道犹存说明寿。",points:[{label:"先读",text:"先辨了解别人和明察自身、战胜别人和克服自身的区别。"},{label:"再辨",text:"知足与强行并读：知道足够，不等于停止必要的实践。"},{label:"后看",text:"不失其所连自察、量力而行；死而不亡依王注读作身没而道存。"}],hint:"自胜者强的强读 qiáng；强行读 qiǎng xíng，取勉力践行义。知人、自知的知均读 zhī。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段释义",tabindex:"-1"},[n("【原典层】原文与段释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段释义","aria-label":'Permalink to "【原典层】原文与段释义"'},"​")],-1)),o(l,{sections:s,glossary:r}),e[2]||(e[2]=a("h2",{id:"【原典层】核心句引读",tabindex:"-1"},[n("【原典层】核心句引读 "),a("a",{class:"header-anchor",href:"#【原典层】核心句引读","aria-label":'Permalink to "【原典层】核心句引读"'},"​")],-1)),o(d,{lines:[{text:"知人者智，自知者明。",tone:"把判断转向自己",guide:"察看别人之前，也察看自身的愿望、偏见与实际能力。"},{text:"知足者富。强行者有志。",tone:"知足与勤行并立",guide:"节制无尽的欲求，同时持续做应做之事；两者并不冲突。"},{text:"死而不亡者寿。",tone:"身没而道犹存",guide:"循王弼看生命之道的延续，勿将寿缩成生理年龄或名声大小。"}]}),e[3]||(e[3]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[n("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),o(h,{items:r}),e[4]||(e[4]=p("",15))])}}})